{
  "name": "@lore-co/opencode",
  "version": "0.2.46",
  "description": "Durable Lore context and capture integration for OpenCode",
  "homepage": "https://docs.uselore.co/agents/opencode",
  "type": "module",
  "main": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./api": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "lore",
    "opencode",
    "memory",
    "plugin"
  ],
  "license": "FSL-1.1-MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/treadiehq/lore.git",
    "directory": "packages/opencode-plugin"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.18",
    "@lore-co/adapter-generic": "0.2.46",
    "@lore-co/cli": "0.2.46",
    "@lore-co/core": "0.2.46",
    "@lore-co/sdk": "0.2.46"
  },
  "devDependencies": {
    "@types/node": "^26.2.0",
    "typescript": "^6.0.3",
    "vitest": "^4.1.11"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "vitest run"
  }
}
